static void /* <=== addvar */ 
addvar(struct treenode **tree, char *var, void *val)
{
	char *old;

	old = treeinsert(tree, var, val);
	if (old)
		free(old);
}

static bool /* <=== space */ 
space(struct scanner *s)
{
	if (!singlespace(s))
		return false;
	while (singlespace(s))
		;
	return true;
}

void /* <=== bufadd */ 
bufadd(struct buffer *buf, char c)
{
	if (buf->len >= buf->cap) {
		buf->cap = buf->cap ? buf->cap * 2 : 1 << 8;
		buf->data = realloc(buf->data, buf->cap);
		if (!buf->data)
			fatal("realloc:");
	}
	buf->data[buf->len++] = c;
}

void /* <=== scannewline */ 
scannewline(struct scanner *s)
{
	switch (s->chr) {
	case '\r':
		crlf(s);
		/* fallthrough */
	case '\n':
		next(s);
		break;
	default:
		scanerror(s, "expected newline");
	}
}

struct evalstring * /* <=== scanstring */ 
scanstring(struct scanner *s, bool path)
{
	struct evalstring *str;
	struct evalstringpart *parts = NULL, **end = &parts;

	buf.len = 0;
	for (;;) {
		switch (s->chr) {
		case '$':
			next(s);
			escape(s, &end);
			break;
		case ':':
		case '|':
		case ' ':
			if (path)
				goto out;
			/* fallthrough */
		default:
			bufadd(&buf, s->chr);
			next(s);
			break;
		case '\r':
		case '\n':
		case EOF:
			goto out;
		}
	}
out:
	if (buf.len > 0)
		addstringpart(&end, 0);
	if (path)
		space(s);
	if (!parts)
		return NULL;
	str = xmalloc(sizeof(*str));
	str->parts = parts;
	str->visited = false;

	return str;
}

static bool /* <=== singlespace */ 
singlespace(struct scanner *s)
{
	int c;

	switch (s->chr) {
	case '$':
		c = getc(s->f);
		switch (c) {
		case '\r':
			crlf(s);
			/* fallthrough */
		case '\n':
			break;
		default:
			ungetc(c, s->f);
			return false;
		}
		/* fallthrough */
	case ' ':
		next(s);
		return true;
	}
	return false;
}

static void /* <=== escape */ 
escape(struct scanner *s, struct evalstringpart ***end)
{
	switch (s->chr) {
	case '$':
	case ' ':
	case ':':
		bufadd(&buf, s->chr);
		next(s);
		break;
	case '{':
		if (buf.len > 0)
			addstringpart(end, false);
		while (isvar(next(s)))
			bufadd(&buf, s->chr);
		if (s->chr != '}')
			scanerror(s, "invalid variable name");
		next(s);
		addstringpart(end, true);
		break;
	case '\r':
		crlf(s);
		/* fallthrough */
	case '\n':
		next(s);
		space(s);
		break;
	default:
		if (buf.len > 0)
			addstringpart(end, false);
		while (issimplevar(s->chr)) {
			bufadd(&buf, s->chr);
			next(s);
		}
		if (!buf.len)
			scanerror(s, "invalid $ escape");
		addstringpart(end, true);
	}
}

static int /* <=== next */ 
next(struct scanner *s)
{
	if (s->chr == '\n') {
		++s->line;
		s->col = 1;
	} else {
		++s->col;
	}
	s->chr = getc(s->f);

	return s->chr;
}

void /* <=== fatal */ 
fatal(const char *fmt, ...)
{
	va_list ap;

	va_start(ap, fmt);
	vwarn(fmt, ap);
	va_end(ap);
	exit(1);
}

static void /* <=== parselet */ 
parselet(struct scanner *s, struct evalstring **val)
{
	scanchar(s, '=');
	*val = scanstring(s, false);
	scannewline(s);
}

char * /* <=== xmemdup */ 
xmemdup(const char *s, size_t n)
{
	char *p;

	p = xmalloc(n);
	memcpy(p, s, n);

	return p;
}

static void /* <=== addstringpart */ 
addstringpart(struct evalstringpart ***end, bool var)
{
	struct evalstringpart *p;

	p = xmalloc(sizeof(*p));
	p->next = NULL;
	**end = p;
	if (var) {
		bufadd(&buf, '\0');
		p->var = xmemdup(buf.data, buf.len);
	} else {
		p->var = NULL;
		p->str = mkstr(buf.len);
		memcpy(p->str->s, buf.data, buf.len);
		p->str->s[buf.len] = '\0';
	}
	*end = &p->next;
	buf.len = 0;
}

void * /* <=== xmalloc */ 
xmalloc(size_t n)
{
	void *p;

	p = malloc(n);
	if (!p)
		fatal("malloc:");

	return p;
}

bool /* <=== scanindent */ 
scanindent(struct scanner *s)
{
	bool indent;

	for (;;) {
		indent = space(s);
		if (!comment(s))
			return indent;
	}
}

char * /* <=== scanname */ 
scanname(struct scanner *s)
{
	name(s);
	return xmemdup(buf.data, buf.len);
}

static bool /* <=== comment */ 
comment(struct scanner *s)
{
	if (s->chr != '#')
		return false;
	do next(s);
	while (s->chr != '\n');
	next(s);
	return true;
}

static void /* <=== crlf */ 
crlf(struct scanner *s)
{
	if (next(s) != '\n')
		scanerror(s, "expected '\\n' after '\\r'");
}

void * /* <=== treeinsert */ 
treeinsert(struct treenode **rootp, char *key, void *value)
{
	struct treenode **a[MAXH], *n = *rootp, *r;
	void *old;
	int i = 0, c;

	a[i++] = rootp;
	while (n) {
		c = strcmp(key, n->key);
		if (c == 0) {
			old = n->value;
			n->value = value;
			return old;
		}
		a[i++] = &n->child[c > 0];
		n = n->child[c > 0];
	}
	r = xmalloc(sizeof(*r));
	r->key = key;
	r->value = value;
	r->child[0] = r->child[1] = NULL;
	r->height = 1;
	/* insert new node, rebalance ancestors.  */
	*a[--i] = r;
	while (i && balance(a[--i]))
		;
	return NULL;
}

static void /* <=== name */ 
name(struct scanner *s)
{
	buf.len = 0;
	while (isvar(s->chr)) {
		bufadd(&buf, s->chr);
		next(s);
	}
	if (!buf.len)
		scanerror(s, "expected name");
	bufadd(&buf, '\0');
	space(s);
}

void /* <=== scanchar */ 
scanchar(struct scanner *s, int c)
{
	if (s->chr != c)
		scanerror(s, "expected '%c'", c);
	next(s);
	space(s);
}

static int /* <=== isvar */ 
isvar(int c)
{
	return issimplevar(c) || c == '.';
}

void /* <=== envaddrule */ 
envaddrule(struct environment *env, struct rule *r)
{
	if (treeinsert(&env->rules, r->name, r))
		fatal("rule '%s' redefined", r->name);
}

static int /* <=== balance */ 
balance(struct treenode **p)
{
	struct treenode *n = *p;
	int h0 = height(n->child[0]);
	int h1 = height(n->child[1]);

	if (h0 - h1 + 1u < 3u) {
		int old = n->height;
		n->height = h0 < h1 ? h1 + 1 : h0 + 1;
		return n->height - old;
	}
	return rot(p, n, h0 < h1);
}

void /* <=== scanerror */ 
scanerror(struct scanner *s, const char *fmt, ...)
{
	extern const char *argv0;
	va_list ap;

	fprintf(stderr, "%s: %s:%d:%d: ", argv0, s->path, s->line, s->col);
	va_start(ap, fmt);
	vfprintf(stderr, fmt, ap);
	va_end(ap);
	putc('\n', stderr);
	exit(1);
}

void /* <=== ruleaddvar */ 
ruleaddvar(struct rule *r, char *var, struct evalstring *val)
{
	addvar(&r->bindings, var, val);
}

static void /* <=== vwarn */ 
vwarn(const char *fmt, va_list ap)
{
	fprintf(stderr, "%s: ", argv0);
	vfprintf(stderr, fmt, ap);
	if (fmt[0] && fmt[strlen(fmt) - 1] == ':') {
		putc(' ', stderr);
		perror(NULL);
	} else {
		putc('\n', stderr);
	}
}

typeDefs:
struct evalstring {
	struct evalstringpart *parts;
	/* used temporarily only in parse.c:parseedge to keep track of
	 * input/output lists before we allocate the arrays. */
	struct evalstring *next;
	/* used to detect cycles when evaluating rule variables */
	_Bool visited;
}

struct scanner {
	FILE *f;
	const char *path;
	int chr, line, col;
}

struct environment {
	struct environment *parent;
	struct treenode *bindings;
	struct treenode *rules;
	struct environment *allnext;
}

vulnerableMethods_after:
static void /* <=== parserule */ 
parserule(struct scanner *s, struct environment *env)
{
	struct rule *r;
	char *var;
	struct evalstring *val;
	bool hascommand = false, hasrspfile = false, hasrspcontent = false;

	r = mkrule(scanname(s));
	scannewline(s);
	while (scanindent(s)) {
		var = scanname(s);
		parselet(s, &val);
		ruleaddvar(r, var, val);
		if (!val)
			continue;
		if (strcmp(var, "command") == 0)
			hascommand = true;
		else if (strcmp(var, "rspfile") == 0)
			hasrspfile = true;
		else if (strcmp(var, "rspfile_content") == 0)
			hasrspcontent = true;
	}
	if (!hascommand)
		fatal("rule '%s' has no command", r->name);
	if (hasrspfile != hasrspcontent)
		fatal("rule '%s' has rspfile and no rspfile_content or vice versa", r->name);
	envaddrule(env, r);
}

